def conjugate(verb):
    suffixes = {
        'ar': ['o', 'as', 'a', 'amos', 'ais', 'an'],
        'er': ['o', 'es', 'e', 'emos', 'eis', 'en'],
        'ir': ['o', 'es', 'e', 'imos', 'is', 'en']
    }

    if verb.endswith('ar'):
        stem = verb[:-2]
        suffix = suffixes['ar']
    elif verb.endswith('er'):
        stem = verb[:-2]
        suffix = suffixes['er']
    elif verb.endswith('ir'):
        stem = verb[:-2]
        suffix = suffixes['ir']
    else:
        return {}

    conjugations = [stem + s for s in suffix]

    return {verb: conjugations}
